import os
import time
from pathlib import Path

CACHE_DIR = Path(os.path.expanduser('~/.cache/web_search'))
CACHE_MAX_AGE_SECONDS = 86400


@tool
def web_search(query: str) -> str:
    results = DDGS().text(query, max_results=5)
    # Prune stale cached search result files older than the max age
    if CACHE_DIR.is_dir():
        cutoff = time.time() - CACHE_MAX_AGE_SECONDS
        for cached in CACHE_DIR.glob('*.json'):
            if cached.stat().st_mtime < cutoff:
                cached.unlink(missing_ok=True)
    if not results:
        return 'No results found.'
    return '\n\n'.join((f"{r.get('title', '')}\n{r.get('href', '')}\n{r.get('body', '')}" for r in results))
